    private Bitmap[] decodeIcons(String[] arr) {
        Bitmap[] r = new Bitmap[arr.length];
        for (int i = 0; i < arr.length; i++) r[i] = decodeIcon(arr[i]);
        return r;
    }

    private Bitmap decodeIcon(String b64) {
        try { byte[] b = android.util.Base64.decode(b64, android.util.Base64.DEFAULT); return BitmapFactory.decodeByteArray(b, 0, b.length); } catch (Exception e) { return null; }
    }
    private Bitmap envIcon() { if (envRowIcon == null) envRowIcon = decodeIcon(ENV_ROW_ICON_B64); return envRowIcon; }
    private Bitmap callIcon() { if (callRowIcon == null) callRowIcon = decodeIcon(CALL_ROW_ICON_B64); return callRowIcon; }
    private Bitmap headIcon() { if (headRowIcon == null) headRowIcon = decodeIcon(CONTACTS_ICON_B64[0]); return headRowIcon; }
    private Bitmap genericIcon() { if (genericRowIcon == null) genericRowIcon = decodeIcon(GENERIC_ROW_ICON_B64); return genericRowIcon; }
    private void loadCatIcons() {
        for (int i = 0; i < CONTACTS_ICON_B64.length; i++) {
            if (contactsIcons[i] == null) {
                try { byte[] b = android.util.Base64.decode(CONTACTS_ICON_B64[i], android.util.Base64.DEFAULT); contactsIcons[i] = BitmapFactory.decodeByteArray(b, 0, b.length); } catch (Exception ignored) { }
            }
        }
        for (int i = 0; i < CALLLOG_ICON_B64.length; i++) {
            if (calllogIcons[i] == null) {
                try { byte[] b = android.util.Base64.decode(CALLLOG_ICON_B64[i], android.util.Base64.DEFAULT); calllogIcons[i] = BitmapFactory.decodeByteArray(b, 0, b.length); } catch (Exception ignored) { }
            }
        }
    }

    private void loadMenuIcons() {
        if (menuIcons[0] != null) return;
        for (int i = 0; i < MENU_ICON_B64.length; i++) {
            try {
                byte[] bytes = android.util.Base64.decode(MENU_ICON_B64[i], android.util.Base64.DEFAULT);
                menuIcons[i] = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
            } catch (Exception ignored) { }
        }
    }

