    @Override
    protected void onDraw(Canvas c) {
        int w = getWidth();
        int h = getHeight();
        drawScreenBackground(c, w, h);
        drawStatus(c, w);
        switch (screen) {
            case IDLE: drawIdle(c, w, h); break;
            case MENU: drawMenu(c, w, h); break;
            case GOTO: drawGoto(c, w, h); break;
            case LIST: drawList(c, w, h); break;
            case PROFILES: drawProfiles(c, w, h); break;
            case ALARM: drawAlarm(c, w, h); break;
            case ALARM_EDIT: drawAlarmEdit(c, w, h); break;
            case CALC: drawCalc(c, w, h); break;
            case CONFIRM_DEL: drawConfirmDelete(c, w, h); break;
            case THREADS: drawThreads(c, w, h); break;
            case CONVERSATION: drawConversation(c, w, h); break;
            case READ: drawRead(c, w, h); break;
            case ADD_CONTACT: drawAddContact(c, w, h); break;
            case COMPOSE_NUMBER:
            case COMPOSE_TEXT: drawCompose(c, w, h); break;
            case DIALER: drawDialer(c, w, h); break;
            case CALLLOG:
            case CONTACTS: drawRows(c, w, h); break;
            case CONTACT_CARD: drawContactCard(c, w, h); break;
            case CONTACTS_HOME: drawIconMenu(c, w, h, "Contacts", CONTACTS_MENU, contactsIcons); break;
            case CALLLOG_HOME: drawIconMenu(c, w, h, "Log", CALLLOG_MENU, calllogIcons); break;
            case OPTIONS: drawOptions(c, w, h); break;
        }
        if (locked) drawLockOverlay(c, w, h);
        if (notice != null) drawNotice(c, w, h);
        if (composeExitConfirm) drawMailboxDialog(c, w, h, "Save message?");
        drawSoftkeys(c, w, h);
    }

    public boolean handleKey(int keyCode) {
        // Sim v4.89 keypad lock: swallow everything except Unlock (left key) then *.
        if (locked) {
            if (keyCode == KeyEvent.KEYCODE_SOFT_LEFT) { unlockPending = true; }
            else if (keyCode == KeyEvent.KEYCODE_STAR && unlockPending) { locked = false; unlockPending = false; }
            else unlockPending = false;
            invalidate();
            return true;
        }
        // Sim v4.89 "Save message?" exit confirm: only Yes/No act, all else swallowed.
        if (composeExitConfirm) {
            if (keyCode == KeyEvent.KEYCODE_SOFT_LEFT || keyCode == KeyEvent.KEYCODE_DPAD_CENTER) {
                if (composeTap.text().length() > 0) {
                    actions.saveDraft(composeNumber.toString(), composeTap.text());
                    notice = "Message saved";
                }
                composeNumber.setLength(0);
                composeTap.clear();
                composeExitConfirm = false;
                listSection = 0;
                listBack.clear();
                listReturn = Screen.IDLE;
                screen = Screen.LIST; // sim lands on the Messaging menu
                row = 0;
            } else if (keyCode == KeyEvent.KEYCODE_SOFT_RIGHT || keyCode == KeyEvent.KEYCODE_BACK) {
                composeNumber.setLength(0);
                composeTap.clear();
                composeExitConfirm = false;
                listSection = 0;
                listBack.clear();
                listReturn = Screen.IDLE;
                screen = Screen.LIST;
                row = 0;
            }
            invalidate();
            return true;
        }
        notice = null; // any fresh key press clears a shown notice
        if (keyCode == KeyEvent.KEYCODE_ENDCALL) {
            composeTap.commit();
            if ((screen == Screen.COMPOSE_NUMBER || screen == Screen.COMPOSE_TEXT)
                    && (composeNumber.length() > 0 || composeTap.text().length() > 0)) {
                composeExitConfirm = true; // sim END on a non-empty compose asks "Save message?"
                invalidate();
                return true;
            }
            screen = Screen.IDLE;
            row = 0;
            invalidate();
            return true;
        }
        if (keyCode == KeyEvent.KEYCODE_SOFT_LEFT && screen == Screen.IDLE) {
            row = 0;
            screen = Screen.GOTO; // sim idle left key is the Go to page
            invalidate();
            return true;
        }
        if (keyCode == KeyEvent.KEYCODE_SOFT_LEFT) {
            if (screen == Screen.OPTIONS) {
                selectCurrent(); // centre/OK equivalent while options open
            } else if (optionsItemsFor(screen).length > 0) {
                openOptions();
            } else if (screen == Screen.LIST) {
                // Sim: an empty left softkey on a list page does nothing.
            } else {
                selectCurrent();
            }
            invalidate();
            return true;
        }
        if (keyCode == KeyEvent.KEYCODE_SOFT_RIGHT && screen == Screen.IDLE) {
            rows = actions.contacts();
            row = 0;
            screen = Screen.CONTACTS;
            invalidate();
            return true;
        }
        if (keyCode == KeyEvent.KEYCODE_SOFT_RIGHT || keyCode == KeyEvent.KEYCODE_BACK) {
            back();
            invalidate();
            return true;
        }
        if (keyCode == KeyEvent.KEYCODE_CALL) {
            callKey();
            invalidate();
            return true;
        }
        if (keyCode >= KeyEvent.KEYCODE_0 && keyCode <= KeyEvent.KEYCODE_9) {
            digit(keyCode - KeyEvent.KEYCODE_0);
            invalidate();
            return true;
        }
        if (keyCode == KeyEvent.KEYCODE_STAR || keyCode == KeyEvent.KEYCODE_POUND) {
            symbol(keyCode == KeyEvent.KEYCODE_STAR ? "*" : "#");
            invalidate();
            return true;
        }
        if (keyCode == KeyEvent.KEYCODE_DEL) {
            deleteKey();
            invalidate();
            return true;
        }
        switch (keyCode) {
            case KeyEvent.KEYCODE_DPAD_UP: move(-1); break;
            case KeyEvent.KEYCODE_DPAD_DOWN: move(1); break;
            case KeyEvent.KEYCODE_DPAD_LEFT: moveHorizontal(-1); break;
            case KeyEvent.KEYCODE_DPAD_RIGHT: moveHorizontal(1); break;
            case KeyEvent.KEYCODE_DPAD_CENTER: selectCurrent(); break;
            default: return false;
        }
        invalidate();
        return true;
    }

    private void digit(int d) {
        switch (screen) {
            case IDLE:
                dialNumber.setLength(0);
                dialNumber.append(d);
                screen = Screen.DIALER;
                break;
            case DIALER:
                if (dialNumber.length() < 24) dialNumber.append(d);
                break;
            case ALARM_EDIT:
                if (alarmDigits.length() < 4) alarmDigits = alarmDigits + d;
                break;
            case CALC:
                if (calc.length() < 12) calc = calc.equals("0") ? String.valueOf(d) : calc + d;
                calcActive = true;
                break;
            case COMPOSE_NUMBER:
                if (resolvedFocus() == 0) {
                    if (composeNumber.length() < 24) composeNumber.append(d);
                } else {
                    handler.removeCallbacks(commitTick);
                    composeTap.press(d);
                    handler.postDelayed(commitTick, 1600);
                }
                break;
            case COMPOSE_TEXT:
                handler.removeCallbacks(commitTick);
                composeTap.press(d);
                handler.postDelayed(commitTick, 1600);
                break;
            case ADD_CONTACT:
                if (contactField == 0) {
                    handler.removeCallbacks(commitTick);
                    nameTap.press(d);
                    handler.postDelayed(commitTick, 1600);
                } else if (contactNumber.length() < 24) contactNumber.append(d);
                break;
            default: break;
        }
    }

    private void symbol(String s) {
        if (screen == Screen.CALC) {
            if (s.equals("*")) {
                if (!calc.contains(".")) calc = (calc.isEmpty() ? "0" : calc) + ".";
            } else {
                calc = calc.isEmpty() ? "-" : jsNum(-parseNum(calc));
            }
            calcActive = true;
        }
        else if (screen == Screen.DIALER && dialNumber.length() < 24) dialNumber.append(s);
        else if (screen == Screen.COMPOSE_NUMBER && resolvedFocus() == 0 && composeNumber.length() < 24) composeNumber.append(s);
        else if (screen == Screen.ADD_CONTACT && contactField == 1 && contactNumber.length() < 24) contactNumber.append(s);
    }

    private void deleteKey() {
        if (screen == Screen.DIALER && dialNumber.length() > 0) {
            dialNumber.deleteCharAt(dialNumber.length() - 1);
        } else if (screen == Screen.COMPOSE_NUMBER) {
            if (resolvedFocus() == 0) {
                if (composeNumber.length() > 0) composeNumber.deleteCharAt(composeNumber.length() - 1);
            } else {
                handler.removeCallbacks(commitTick);
                composeTap.backspace();
            }
        } else if (screen == Screen.COMPOSE_TEXT) {
            handler.removeCallbacks(commitTick);
            composeTap.backspace();
        } else if (screen == Screen.ADD_CONTACT) {
            if (contactField == 0) {
                handler.removeCallbacks(commitTick);
                nameTap.backspace();
            } else if (contactNumber.length() > 0) contactNumber.deleteCharAt(contactNumber.length() - 1);
        }
    }

    private void callKey() {
        switch (screen) {
            case DIALER:
                if (dialNumber.length() > 0) {
                    actions.dial(dialNumber.toString());
                    screen = Screen.IDLE;
                    dialNumber.setLength(0);
                }
                break;
            case CALLLOG:
                if (!rows.isEmpty()) {
                    actions.dial(rows.get(row)[3]);
                    screen = Screen.IDLE;
                    row = 0;
                }
                break;
            case CONTACTS:
                if (!rows.isEmpty()) {
                    actions.dial(rows.get(row)[1]);
                    screen = Screen.IDLE;
                    row = 0;
                }
                break;
            case THREADS:
                if (!convos.isEmpty()) {
                    actions.dial(convos.get(row).address);
                    screen = Screen.IDLE;
                    row = 0;
                }
                break;
            case CONVERSATION:
                if (convoAddress != null) {
                    actions.dial(convoAddress);
                    screen = Screen.IDLE;
                    row = 0;
                }
                break;
            case CONTACT_CARD:
                // Sim OK on the contact page calls the number.
                actions.dial(cardNumber);
                screen = Screen.IDLE;
                row = 0;
                break;
            case READ:
                if (!threads.isEmpty()) {
                    actions.dial(threads.get(readIndex).address);
                    screen = Screen.IDLE;
                }
                break;
            default:
                screen = Screen.DIALER;
                dialNumber.setLength(0);
                break;
        }
    }

    // MainActivity calls this when a background refresh has new data, so a
    // visible list re-reads the cache (never the provider) and repaints.
    public void dataChanged() {
        if (screen == Screen.THREADS) {
            threads = actions.sms();
            rebuildConvos();
        } else if (screen == Screen.CALLLOG) {
            rows = actions.callLog();
        } else if (screen == Screen.CONTACTS) {
            rows = actions.contacts();
        }
        invalidate();
    }

    private void rebuildConvos() {
        convos = new ArrayList<>();
        for (PhoneStore.Sms m : threads) {
            boolean seen = false;
            for (PhoneStore.Sms x : convos) {
                if (x.address != null && x.address.equals(m.address)) { seen = true; break; }
            }
            if (!seen) convos.add(m);
        }
    }

    private void openConversation(String address) {
        convoAddress = address;
        convoMsgs = new ArrayList<>();
        for (int i = threads.size() - 1; i >= 0; i--) {
            PhoneStore.Sms m = threads.get(i);
            if (m.address != null && m.address.equals(address)) convoMsgs.add(m);
        }
        row = convoMsgs.isEmpty() ? 0 : convoMsgs.size() - 1;
        screen = Screen.CONVERSATION;
    }

    private String timeLabel(long date) {
        return new java.text.SimpleDateFormat("HH:mm", java.util.Locale.UK).format(new java.util.Date(date));
    }

    private String dayLabel(long date) {
        return new java.text.SimpleDateFormat("dd-MM-yyyy", java.util.Locale.UK).format(new java.util.Date(date));
    }

    private void back() {
        switch (screen) {
            case OPTIONS: screen = optionsFrom; break;
            case MENU: screen = Screen.IDLE; row = 0; break;
            case GOTO: screen = Screen.IDLE; row = 0; break;
            case ALARM:
                if (alarmFromList) { screen = Screen.LIST; listSection = 1; row = 0; }
                else { screen = Screen.GOTO; row = 2; }
                break;
            case CALC:
                if (!calcActive) {
                    if (calcFromList) { screen = Screen.LIST; listSection = 1; row = 5; }
                    else { screen = Screen.GOTO; row = 5; }
                } else {
                    calc = calc.isEmpty() ? "" : calc.substring(0, calc.length() - 1);
                    calcActive = !calc.isEmpty();
                }
                break;
            case ALARM_EDIT:
                if (alarmDigits.length() > 0) alarmDigits = alarmDigits.substring(0, alarmDigits.length() - 1);
                else screen = Screen.ALARM;
                break;
            case PROFILES:
                if (profilesFromSettings) {
                    profilesFromSettings = false;
                    screen = Screen.LIST;
                    listSection = 37;
                    row = 0;
                } else {
                    screen = Screen.GOTO;
                    row = 1;
                }
                break;
            case CONFIRM_DEL: screen = Screen.LIST; listSection = 23; row = 2; break;
            case LIST:
                if (listSection == 32) { listSection = 0; screen = Screen.COMPOSE_NUMBER; row = 0; }
                else if (!listBack.isEmpty()) { listSection = listBack.pop(); row = 0; }
                else { screen = listReturn; row = 0; }
                break;
            case THREADS: screen = Screen.LIST; row = 0; break;
            case COMPOSE_NUMBER:
                // Sim right key: Clear the focused field first, Back only when empty.
                if (composeNumber.length() > 0 || composeTap.text().length() > 0) clearComposeField();
                else { screen = Screen.LIST; row = 0; }
                break;
            case CONVERSATION: screen = Screen.THREADS; row = 0; break;
            case READ: screen = convoAddress != null ? Screen.CONVERSATION : Screen.THREADS; break;
            case COMPOSE_TEXT: screen = Screen.COMPOSE_NUMBER; break;
            case DIALER:
                if (dialNumber.length() > 0) dialNumber.setLength(0); // sim: right key is Clear first
                else screen = Screen.IDLE;
                break;
            case ADD_CONTACT:
                if (editingContact) {
                    // Sim: right key while editing cancels the edit, no Clear step.
                    handler.removeCallbacks(commitTick);
                    nameTap.clear();
                    contactNumber.setLength(0);
                    editingContact = false;
                    screen = Screen.CONTACT_CARD;
                    row = 0;
                } else if (nameTap.text().length() > 0 || contactNumber.length() > 0) {
                    // Sim right key: Clear the active field first, Back only when empty.
                    if (contactField == 0) { handler.removeCallbacks(commitTick); nameTap.clear(); }
                    else contactNumber.setLength(0);
                } else { screen = Screen.CONTACTS_HOME; row = 0; }
                break;
            case CALLLOG: screen = Screen.CALLLOG_HOME; row = 0; break;
            case CONTACTS: screen = Screen.IDLE; row = 0; break; // sim names right key is Exit
            case CONTACT_CARD: screen = Screen.CONTACTS; row = 0; break;
            case CONTACTS_HOME: case CALLLOG_HOME: screen = Screen.MENU; row = 0; break;
            default: break;
        }
    }

    private void move(int delta) {
        if (screen == Screen.CALC) { calcOperator(delta < 0 ? "+" : "\u2212"); return; } // sim: UP=+, DOWN=-
        if (screen == Screen.OPTIONS) {
            if (optionsItems.length > 0) optionsSel = (optionsSel + delta + optionsItems.length) % optionsItems.length;
            return;
        }
        if (screen == Screen.MENU) {
            selected = (selected + delta * 3 + MENU_ITEMS.length) % MENU_ITEMS.length;
            return;
        }
        if (screen == Screen.ADD_CONTACT) { contactField = 1 - contactField; return; }
        if (screen == Screen.COMPOSE_NUMBER) {
            if (resolvedFocus() == 0) {
                if (delta > 0) { // DOWN: into the text, or the picker when no recipient yet (sim)
                    if (composeNumber.length() > 0) composeFocus = 1; else openRecipientPicker();
                }
            } else if (delta < 0) composeFocus = 0; // UP: back to the To: field
            return;
        }
        int count = listCount();
        if (count == 0) return;
        row = (row + delta + count) % count;
    }

    private void moveHorizontal(int delta) {
        if (screen == Screen.CALC) { calcOperator(delta < 0 ? "\u00D7" : "\u00F7"); return; } // sim: LEFT=x, RIGHT=/
        if (screen == Screen.MENU) {
            selected = (selected + delta + MENU_ITEMS.length) % MENU_ITEMS.length;
        }
    }

    private int listCount() {
        switch (screen) {
            case GOTO: return GOTO_ROWS.length;
            case PROFILES: return PROFILE_ROWS.length;
            case ALARM: return 5;
            case LIST: return listSection == 11 ? drafts.size() : LIST_ITEMS[listSection].length;
            case THREADS: return convos.size();
            case CONVERSATION: return Math.max(convoMsgs.size(), 1);
            case CALLLOG: case CONTACTS: return rows.size();
            case CONTACT_CARD: return 1; // sim: just the number row
            case CONTACTS_HOME: return CONTACTS_MENU.length;
            case CALLLOG_HOME: return CALLLOG_MENU.length;
            default: return 0;
        }
    }

    private void selectCurrent() {
        switch (screen) {
            case OPTIONS:
                activateOption();
                break;
            case IDLE:
                screen = Screen.MENU;
                selected = 0;
                row = 0;
                break;
            case MENU:
                openMenuItem(MENU_ITEMS[selected]);
                break;
            case GOTO:
                gotoSelect(row);
                break;
            case PROFILES:
                activateProfile();
                break;
            case ALARM:
                alarmChange();
                break;
            case ALARM_EDIT:
                alarmSave();
                break;
            case CALC:
                calcEquals();
                break;
            case CONFIRM_DEL:
                deleteAllMessages();
                break;
            case LIST:
                selectListItem();
                break;
            case CONTACTS_HOME:
                if (row == 0) {
                    rows = actions.contacts();
                    screen = Screen.CONTACTS;
                } else if (row == 1) { // Add new: the sim's form page
                    nameTap.clear();
                    contactNumber.setLength(0);
                    contactField = 0;
                    editingContact = false;
                    screen = Screen.ADD_CONTACT;
                } else {
                    listSection = row; // 2..7 map onto the sim's static pages
                    listBack.clear();
                    listReturn = Screen.CONTACTS_HOME;
                    screen = Screen.LIST;
                }
                row = 0;
                break;
            case ADD_CONTACT:
                handler.removeCallbacks(commitTick);
                nameTap.commit();
                if (nameTap.text().length() == 0) {
                    notice = "Enter a name"; // sim saveContact() refuses empty names
                    break;
                }
                if (editingContact) {
                    if (actions.updateContact(cardName, cardNumber, nameTap.text(), contactNumber.toString())) {
                        cardName = nameTap.text();
                        cardNumber = contactNumber.toString();
                        rows = actions.contacts();
                    }
                    editingContact = false;
                    screen = Screen.CONTACT_CARD; // sim saveContact(): go('contact')
                    row = 0;
                } else {
                    if (actions.addContact(nameTap.text(), contactNumber.toString())) {
                        rows = actions.contacts();
                        screen = Screen.CONTACTS;
                        row = 0;
                    }
                }
                break;
            case CALLLOG_HOME:
                if (row <= 4) {
                    callLogTitle = CALLLOG_MENU[row];
                    rows = actions.callLog();
                    if (row == 1) rows = filterCallRows(rows, "Missed");
                    else if (row == 2) rows = filterCallRows(rows, "Incoming");
                    else if (row == 3) rows = filterCallRows(rows, "Outgoing");
                    else if (row == 4) { // Message recipients: latest SMS per address
                        rows = new ArrayList<>();
                        java.util.LinkedHashSet<String> seen = new java.util.LinkedHashSet<>();
                        for (PhoneStore.Sms m : actions.sms()) {
                            if (seen.add(m.address)) rows.add(new String[]{m.address, "Message", m.dateLabel(), m.address});
                        }
                    }
                    screen = Screen.CALLLOG;
                } else {
                    listSection = row + 3; // 5..7 -> sections 8..10
                    listBack.clear();
                    listReturn = Screen.CALLLOG_HOME;
                    screen = Screen.LIST;
                }
                row = 0;
                break;
            case THREADS:
                if (!convos.isEmpty()) openConversation(convos.get(row).address);
                break;
            case CONVERSATION:
                if (!convoMsgs.isEmpty() && row < convoMsgs.size()) {
                    int idx = threads.indexOf(convoMsgs.get(row));
                    readIndex = Math.max(idx, 0);
                    screen = Screen.READ;
                }
                break;
            case READ:
                if (!threads.isEmpty()) {
                    composeNumber.setLength(0);
                    composeNumber.append(threads.get(readIndex).address);
                    composeTap.clear();
                    screen = Screen.COMPOSE_NUMBER;
                }
                break;
            case COMPOSE_NUMBER:
                if (resolvedFocus() == 0) {
                    openRecipientPicker(); // sim: centre key on To: opens the recipient picker
                } else {
                    sendCompose();
                }
                break;
            case COMPOSE_TEXT:
                sendCompose();
                break;
            case DIALER:
                if (dialNumber.length() > 0) {
                    actions.dial(dialNumber.toString());
                    screen = Screen.IDLE;
                    dialNumber.setLength(0);
                }
                break;
            case CALLLOG:
                if (!rows.isEmpty()) {
                    actions.dial(rows.get(row)[3]);
                    screen = Screen.IDLE;
                    row = 0;
                }
                break;
            case CONTACTS:
                if (!rows.isEmpty()) {
                    cardName = rows.get(row)[0];
                    cardNumber = rows.get(row)[1];
                    screen = Screen.CONTACT_CARD;
                    row = 0;
                }
                break;
        }
    }

    private void openMenuItem(String item) {
        switch (item) {
            case "Messaging":
                listSection = 0;
                listBack.clear();
                listReturn = Screen.MENU;
                screen = Screen.LIST;
                row = 0;
                break;
            case "Organiser":
                listSection = 1;
                listBack.clear();
                listReturn = Screen.MENU;
                screen = Screen.LIST;
                row = 0;
                break;
            case "Contacts":
                loadCatIcons();
                screen = Screen.CONTACTS_HOME;
                row = 0;
                break;
            case "Log":
                loadCatIcons();
                screen = Screen.CALLLOG_HOME;
                row = 0;
                break;
            case "Media":
                listSection = 29;
                listBack.clear();
                listReturn = Screen.MENU;
                screen = Screen.LIST;
                row = 0;
                break;
            case "Apps.":
                listSection = 30;
                listBack.clear();
                listReturn = Screen.MENU;
                screen = Screen.LIST;
                row = 0;
                break;
            case "Settings":
                listSection = 37;
                listBack.clear();
                listReturn = Screen.MENU;
                screen = Screen.LIST;
                row = 0;
                break;
            case "Gallery":
                listSection = 38;
                listBack.clear();
                listReturn = Screen.MENU;
                screen = Screen.LIST;
                row = 0;
                break;
            case "STORE":
                listSection = 39; // sim titles this page "Web"
                listBack.clear();
                listReturn = Screen.MENU;
                screen = Screen.LIST;
                row = 0;
                break;
            default:
                actions.openRoute("Menu", item);
                break;
        }
    }

    private static List<String[]> filterCallRows(List<String[]> all, String typeLabel) {
        List<String[]> out = new ArrayList<>();
        for (String[] r : all) if (r.length > 1 && typeLabel.equals(r[1])) out.add(r);
        return out;
    }

    private void openListSection(int s) {
        if (screen == Screen.LIST) listBack.push(listSection);
        listSection = s;
        screen = Screen.LIST;
        row = 0;
        if (s == 11) { // Drafts: real, saved from the composer exit confirm
            drafts.clear();
            drafts.addAll(actions.drafts());
        }
    }

    private static final int[] MSG_FOLDER_SECTIONS = {11, 12, 13, 14, 17, 18, 19, 20, 21, 22, 23, 24};

    // Sim v4.89: centre key on the To: field, DOWN on an empty To:, and
    // "Add recipient >" all open the recipient picker page.
    private void openRecipientPicker() {
        listBack.clear();
        listSection = 32;
        row = 0;
        screen = Screen.LIST;
    }

    private void selectListItem() {
        if (listSection == 33) { // Sim createmessage routes
            if (row == 0) { // Message -> the composer
                composeNumber.setLength(0);
                composeTap.clear();
                composeSent = false;
                screen = Screen.COMPOSE_NUMBER;
            } else if (row == 3) openListSection(15); // Templates
            else openListSection(33 + row); // 34 Flash, 35 Audio
            return;
        }
        if (listSection == 32) { // Sim recipient picker: only Contacts navigates
            if (row == 3) { rows = actions.contacts(); row = 0; screen = Screen.CONTACTS; }
            else notice = LIST_ITEMS[32][row] + " opened";
            return;
        }
        if (listSection == 0) {
            if (row == 0) { // Create message -> the sim's submenu page
                openListSection(33);
            } else if (row == 1) { // Conversations
                threads = actions.sms();
            rebuildConvos();
                screen = Screen.THREADS;
                row = 0;
            } else { // rows 2..13 -> the sim's folder/settings pages
                openListSection(MSG_FOLDER_SECTIONS[row - 2]);
            }
            return;
        }
        if (listSection == 11) { // Drafts: Edit reopens the composer prefilled
            if (!drafts.isEmpty() && row < drafts.size()) {
                String[] d = drafts.get(row);
                composeNumber.setLength(0);
                composeNumber.append(d[0]);
                composeTap.set(d[1]);
                composeSent = false;
                screen = Screen.COMPOSE_NUMBER;
            }
            return;
        }
        if (listSection == 14) { // Saved items -> Templates / Saved messages
            openListSection(row == 0 ? 15 : 16);
            return;
        }
        if (listSection == 23) { // Sim deletemessages routes
            if (row == 0) { // By message -> the message list
                threads = actions.sms();
                rebuildConvos();
                screen = Screen.THREADS;
                row = 0;
            } else if (row == 1) openListSection(36); // By folder -> My folders
            else screen = Screen.CONFIRM_DEL; // All messages -> sim confirm page
            return;
        }
        if (listSection == 36) { // My folders -> Saved messages / Templates
            openListSection(row == 0 ? 16 : 15);
            return;
        }
        if (listSection == 37) { // Sim settings routes: only Profiles is built
            if (row == 0) {
                profilesFromSettings = true;
                screen = Screen.PROFILES;
                row = 0;
            }
            return;
        }
        if (listSection == 24) { // Message settings -> the five settings pages
            openListSection(25 + row);
            return;
        }
        if (listSection == 1) {
            if (row == 0) { // sim organiser row 0 opens the alarm clock page
                alarmFromList = true;
                screen = Screen.ALARM;
                row = 0;
                return;
            }
            if (row == 5) { // sim organiser row 5 opens the calculator page
                calcFromList = true;
                screen = Screen.CALC;
                return;
            }
            actions.openRoute(LIST_TITLES[listSection], LIST_ITEMS[listSection][row]);
        }
        // Remaining sections are sim-static pages: rows are information only.
    }

    private String timeLabel() {
        return new SimpleDateFormat("HH:mm", Locale.UK).format(new Date());
    }

    private String dateLabel() {
        return new SimpleDateFormat("EEE d MMM", Locale.UK).format(new Date());
    }

    // ------------------------------------------------------------------
    // Reborn v4.89 skin: tokens lifted from the frozen c2-reborn source
    // (index.html v4.89 final-release). Reference frame: 240x320 LCD -
    // status 26px, screen 258px, soft bar 36px. Scaled to this canvas.
    // ------------------------------------------------------------------
    private static final int COL_STATUS_BG = Color.parseColor("#050708");
    private static final int COL_SOFT_BG = Color.parseColor("#020304");
    private static final int COL_SCREEN_BG = Color.parseColor("#252728");
    private static final int COL_TITLE_BG = Color.parseColor("#77A9C1");
    private static final int COL_SUB = Color.parseColor("#CCCCCC");
    private static final int COL_HOME_TEXT = Color.parseColor("#078DF0");
    private static final int COL_READ_BG = Color.parseColor("#F4F4F4");
    private static final int COL_READ_FG = Color.parseColor("#111111");
    private static final int COL_ACCENT = Color.parseColor("#43BEE9");

    private float statusH(int h) { return h * 0.08125f; }
    private float softTop(int h) { return h * 0.8875f; }
    private float screenH(int h) { return softTop(h) - statusH(h); }

    // Sim v4.89: app screens are BLACK with the grey swoosh wallpaper, not flat #252728.
    private void drawScreenBackground(Canvas c, int w, int h) {
        p.setStyle(Paint.Style.FILL);
        p.setColor(Color.BLACK);
        c.drawRect(0, 0, w, h, p);
        drawSwoosh(c, w, h);
    }

    // Frozen sim's screen-bg-default.svg swoosh (three translucent grey bands), drawn as paths.
    private void drawSwoosh(Canvas c, int w, int h) {
        float sw = w / 244f, sh = h / 362f;
        android.graphics.Path p1 = new android.graphics.Path();
        p1.moveTo(0, 24 * sh);
        p1.cubicTo(23 * sw, 102 * sh, 105 * sw, 153 * sh, 244 * sw, 96 * sh);
        p1.lineTo(244 * sw, 142 * sh);
        p1.cubicTo(109 * sw, 188 * sh, 28 * sw, 146 * sh, 0, 71 * sh);
        p1.close();
        p.setStyle(Paint.Style.FILL);
        p.setColor(Color.parseColor("#9E888888"));
        c.drawPath(p1, p);
        android.graphics.Path p2 = new android.graphics.Path();
        p2.moveTo(0, 128 * sh);
        p2.cubicTo(72 * sw, 185 * sh, 149 * sw, 222 * sh, 244 * sw, 258 * sh);
        p2.lineTo(244 * sw, 314 * sh);
        p2.cubicTo(139 * sw, 282 * sh, 48 * sw, 224 * sh, 0, 178 * sh);
        p2.close();
        p.setColor(Color.parseColor("#80999999"));
        c.drawPath(p2, p);
        android.graphics.Path p3 = new android.graphics.Path();
        p3.moveTo(244 * sw, 70 * sh);
        p3.cubicTo(187 * sw, 134 * sh, 145 * sw, 237 * sh, 126 * sw, 362 * sh);
        p3.lineTo(181 * sw, 362 * sh);
        p3.cubicTo(187 * sw, 255 * sh, 210 * sw, 147 * sh, 244 * sw, 112 * sh);
        p3.close();
        p.setColor(Color.parseColor("#45AAAAAA"));
        c.drawPath(p3, p);
    }

    private void drawStatus(Canvas c, int w) {
        float sh = statusH(getHeight());
        p.setStyle(Paint.Style.FILL);
        p.setColor(COL_STATUS_BG);
        c.drawRect(0, 0, w, sh, p);
        p.setColor(Color.WHITE);
        // Signal glyph: four ascending bars (v4.89 status asset look).
        float base = sh * 0.78f;
        float bw = w * 0.018f;
        for (int b = 0; b < 4; b++) {
            float bh = sh * (0.22f + 0.14f * b);
            float x0 = w * 0.025f + b * bw * 1.45f;
            c.drawRect(x0, base - bh, x0 + bw, base, p);
        }
        // Battery glyph with live fill level.
        int batt = actions.batteryPercent();
        float bx = w * 0.135f, by = sh * 0.26f, bwid = w * 0.075f, bhei = sh * 0.48f;
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(sh * 0.06f);
        c.drawRect(bx, by, bx + bwid, by + bhei, p);
        c.drawRect(bx + bwid, by + bhei * 0.3f, bx + bwid + w * 0.008f, by + bhei * 0.7f, p);
        if (batt >= 0) {
            p.setStyle(Paint.Style.FILL);
            float pad = sh * 0.08f;
            float fill = (bwid - 2 * pad) * Math.max(0, Math.min(100, batt)) / 100f;
            c.drawRect(bx + pad, by + pad, bx + pad + fill, by + bhei - pad, p);
        }
        // Time, right-aligned, condensed narrow face.
        p.setStyle(Paint.Style.FILL);
        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
        p.setTextSize(sh * 0.62f);
        p.setTextAlign(Paint.Align.RIGHT);
        c.drawText(timeLabel(), w * 0.965f, sh * 0.72f, p);
        p.setTextAlign(Paint.Align.LEFT);
        p.setTypeface(Typeface.DEFAULT);
    }

    private void drawIdle(Canvas c, int w, int h) {
        float top = statusH(h), bot = softTop(h);
        // v4.89 home wallpaper: 160deg linear gradient + radial highlight.
        android.graphics.LinearGradient lg = new android.graphics.LinearGradient(
                0, top, w, bot,
                new int[]{Color.parseColor("#D7E2F6"), Color.parseColor("#B6CBEA"),
                          Color.parseColor("#6F96CD"), Color.parseColor("#325F9E")},
                new float[]{0f, 0.37f, 0.68f, 1f}, android.graphics.Shader.TileMode.CLAMP);
        p.setStyle(Paint.Style.FILL);
        p.setShader(lg);
        c.drawRect(0, top, w, bot, p);
        android.graphics.RadialGradient rg = new android.graphics.RadialGradient(
                w * 0.64f, top + (bot - top) * 0.30f, (bot - top) * 0.34f,
                Color.argb(107, 155, 190, 239), Color.TRANSPARENT,
                android.graphics.Shader.TileMode.CLAMP);
        p.setShader(rg);
        c.drawRect(0, top, w, bot, p);
        p.setShader(null);

        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
        p.setColor(COL_HOME_TEXT);
        // Clock top-right: 24px at 240px LCD width (v4.89 token).
        p.setTextSize(w * 0.10f);
        p.setTextAlign(Paint.Align.RIGHT);
        c.drawText(timeLabel(), w * 0.9625f, top + (bot - top) * 0.039f + w * 0.085f, p);
        // Carrier top-left, date below: 12px at 240 (v4.89 token).
        p.setTextAlign(Paint.Align.LEFT);
        p.setTextSize(w * 0.05f);
        String carrier = carrierName();
        float ty = top + (bot - top) * 0.039f + w * 0.045f;
        if (!carrier.isEmpty()) {
            c.drawText(carrier, w * 0.042f, ty, p);
            ty += w * 0.062f;
        }
        c.drawText(new SimpleDateFormat("EEE dd-MM-yyyy", Locale.UK).format(new Date()), w * 0.042f, ty, p);

        // S40-style idle notification: small light box, only when there is one.
        int missed = actions.missedCalls();
        int unread = actions.unreadSms();
        if (missed > 0 || unread > 0) {
            List<String> lines = new ArrayList<>();
            if (unread > 0) lines.add(unread + (unread == 1 ? " new message" : " new messages"));
            if (missed > 0) lines.add(missed + (missed == 1 ? " missed call" : " missed calls"));
            float boxW = w * 0.62f;
            float boxH = w * 0.075f + lines.size() * w * 0.085f;
            float bx = (w - boxW) / 2f;
            float by = top + (bot - top) * 0.52f - boxH / 2f;
            p.setStyle(Paint.Style.FILL);
            p.setColor(Color.WHITE);
            c.drawRect(bx, by, bx + boxW, by + boxH, p);
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(w * 0.004f);
            p.setColor(Color.parseColor("#888888"));
            c.drawRect(bx, by, bx + boxW, by + boxH, p);
            p.setStyle(Paint.Style.FILL);
            p.setColor(COL_READ_FG);
            p.setTextAlign(Paint.Align.CENTER);
            p.setTextSize(w * 0.071f);
            float ly = by + w * 0.085f;
            for (String line : lines) {
                c.drawText(line, w * 0.5f, ly, p);
                ly += w * 0.085f;
            }
        }
        p.setTextAlign(Paint.Align.LEFT);
        p.setTypeface(Typeface.DEFAULT);
    }

    private String carrierName() {
        try {
            android.telephony.TelephonyManager tm = (android.telephony.TelephonyManager)
                    getContext().getSystemService(Context.TELEPHONY_SERVICE);
            if (tm != null) {
                String n = tm.getNetworkOperatorName();
                if (n != null && !n.trim().isEmpty()) return n.trim();
            }
        } catch (Throwable ignored) { }
        return "";
    }

    private void drawMenu(Canvas c, int w, int h) {
        loadMenuIcons();
        // Sim v4.89 menu: small plain title top-left (no blue bar), 3x3 icon
        // grid on the dark screen, white labels, inverted selection.
        float top = statusH(h);
        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
        p.setColor(Color.WHITE);
        p.setTextAlign(Paint.Align.LEFT);
        p.setTextSize(w * 0.058f);
        c.drawText("Menu", w * 0.03f, top + w * 0.075f, p);

        float gridTop = top + w * 0.11f;
        float gridBot = softTop(h);
        float cellH = (gridBot - gridTop) / 3f;
        float cellW = w / 3f;
        float iconSize = Math.min(cellW, cellH) * 0.46f;
        for (int i = 0; i < MENU_ITEMS.length; i++) {
            float cx = (i % 3) * cellW + cellW / 2f;
            float cy = (i / 3) * cellH + gridTop + cellH / 2f;
            boolean sel = i == selected;
            if (sel) {
                // Sim .cell.sel: dark gradient #666->#050505, 1px #aaa border, 6px radius.
                float pad = cellW * 0.06f;
                float l = (i % 3) * cellW + pad, t2 = (i / 3) * cellH + gridTop + pad;
                float r = (i % 3) * cellW + cellW - pad, b = (i / 3) * cellH + gridTop + cellH - pad;
                float rad = w * (6f / 240f);
                p.setStyle(Paint.Style.FILL);
                p.setShader(new android.graphics.LinearGradient(0, t2, 0, b,
                        Color.parseColor("#666666"), Color.parseColor("#050505"),
                        android.graphics.Shader.TileMode.CLAMP));
                c.drawRoundRect(new android.graphics.RectF(l, t2, r, b), rad, rad, p);
                p.setShader(null);
                p.setStyle(Paint.Style.STROKE);
                p.setStrokeWidth(w * (1f / 240f));
                p.setColor(Color.parseColor("#AAAAAA"));
                c.drawRoundRect(new android.graphics.RectF(l, t2, r, b), rad, rad, p);
                p.setStyle(Paint.Style.FILL);
            }
            Bitmap icon = menuIcons[MENU_ICON_MAP[i]];
            if (icon != null) {
                float ix = cx - iconSize / 2f;
                float iy = cy - iconSize * 0.62f;
                android.graphics.Rect dst = new android.graphics.Rect(
                        (int) ix, (int) iy, (int) (ix + iconSize), (int) (iy + iconSize));
                c.drawBitmap(icon, null, dst, p); // sim selection keeps the icon unfiltered
            }
            p.setStyle(Paint.Style.FILL);
            p.setColor(Color.WHITE); // sim cell text stays white even when selected
            p.setTextSize(w * 0.046f);
            p.setTextAlign(Paint.Align.CENTER);
            c.drawText(MENU_ITEMS[i], cx, cy + iconSize * 0.62f, p);
        }
        p.setTextAlign(Paint.Align.LEFT);
        p.setTypeface(Typeface.DEFAULT);
    }


    private float titleH(int h) { return screenH(h) * 0.097f; }

    private Bitmap listIconFor(int idx) {
        if (listSection == 0 || (listSection == 33 && idx == 0)) {
            if (msgIcons == null) {
                msgIcons = new Bitmap[MSG_ICON_B64.length];
                for (int i = 0; i < MSG_ICON_B64.length; i++) {
                    try { byte[] b = android.util.Base64.decode(MSG_ICON_B64[i], android.util.Base64.DEFAULT); msgIcons[i] = BitmapFactory.decodeByteArray(b, 0, b.length); } catch (Exception ignored) { }
                }
            }
            return msgIcons[idx < 4 ? idx : 4];
        }
        if (listSection == 39) {
            if (storeIcons == null) {
                storeIcons = new Bitmap[STORE_ICON_B64.length];
                for (int i = 0; i < STORE_ICON_B64.length; i++) {
                    try { byte[] b = android.util.Base64.decode(STORE_ICON_B64[i], android.util.Base64.DEFAULT); storeIcons[i] = BitmapFactory.decodeByteArray(b, 0, b.length); } catch (Exception ignored) { }
                }
            }
            return storeIcons[idx];
        }
        if (listSection == 38 && idx == 0) {
            if (galleryMcIcon == null) {
                try { byte[] b = android.util.Base64.decode(GALLERY_MC_ICON_B64, android.util.Base64.DEFAULT); galleryMcIcon = BitmapFactory.decodeByteArray(b, 0, b.length); } catch (Exception ignored) { }
            }
            return galleryMcIcon;
        }
        if (listSection == 1) { // sim organiser: 7 listIcons ids, row 7 falls back to assets[6]
            if (orgIcons == null) orgIcons = decodeIcons(ORG_ICON_B64);
            return idx < ORG_ICON_B64.length ? orgIcons[idx] : genericIcon();
        }
        if (listSection == 31) { // sim media: icons on rows 0,1,3; rows 2,4,5 fall back to assets[5]
            if (medIcons == null) medIcons = decodeIcons(MED_ICON_B64);
            if (mediaFbIcon == null) mediaFbIcon = decodeIcon(MEDIA_FB_ICON_B64);
            return idx == 0 ? medIcons[0] : idx == 1 ? medIcons[1] : idx == 3 ? medIcons[2] : mediaFbIcon;
        }
        if (listSection == 37) { // sim settings: 8 listIcons ids
            if (setIcons == null) setIcons = decodeIcons(SET_ICON_B64);
            return idx < SET_ICON_B64.length ? setIcons[idx] : genericIcon();
        }
        if (genericRowIcon == null) {
            try { byte[] b = android.util.Base64.decode(GENERIC_ROW_ICON_B64, android.util.Base64.DEFAULT); genericRowIcon = BitmapFactory.decodeByteArray(b, 0, b.length); } catch (Exception ignored) { }
        }
        return genericRowIcon;
    }

    private void drawList(Canvas c, int w, int h) {
        String titleRight = null;
        if (listSection == 1 || listSection == 37) titleRight = "\u2026"; // sim "..."
        else if (listSection == 38 || listSection == 39) titleRight = "1"; // sim count
        drawTitle(c, w, h, LIST_TITLES[listSection], titleRight);
        if (listSection == 11) { // Drafts: live list, not the static stub
            if (drafts.isEmpty()) {
                drawEmpty(c, w, h, "No drafts");
                return;
            }
            drawItemRows(c, w, h, drafts.size(), i -> drafts.get(i)[1], i -> drafts.get(i)[0], i -> genericIcon());
            return;
        }
        if (listSection == 33) { // Sim createmessage: envelope row 0, glyphs, Flash row disabled
            String[] items = LIST_ITEMS[33];
            String[] glyphs = {"", "\u2301", "\u2709", "\u2709"};
            float listTop = statusH(h) + titleH(h);
            float rowH = (softTop(h) - listTop) / 5f;
            float padX = w * 0.035f;
            int disCol = Color.parseColor("#555555"); // sim .disabled
            for (int i = 0; i < items.length; i++) {
                float top = listTop + i * rowH;
                if (i == row) drawSelPill(c, w, top, rowH);
                int col = i == 1 ? disCol : Color.WHITE;
                float textX = padX;
                if (i == 0) {
                    Bitmap ic = listIconFor(0);
                    if (ic != null) {
                        float iconSize = rowH * 0.60f;
                        float cy = top + rowH / 2f;
                        android.graphics.Rect dst = new android.graphics.Rect(
                                (int) padX, (int) (cy - iconSize / 2f),
                                (int) (padX + iconSize), (int) (cy + iconSize / 2f));
                        c.drawBitmap(ic, null, dst, p);
                    }
                    textX = padX + rowH * 0.60f + w * 0.035f;
                } else {
                    p.setTextAlign(Paint.Align.LEFT);
                    p.setTextSize(w * 0.078f);
                    p.setColor(col);
                    c.drawText(glyphs[i], padX + rowH * 0.14f, top + rowH * 0.62f, p);
                    textX = padX + rowH * 0.60f + w * 0.035f;
                }
                p.setTextAlign(Paint.Align.LEFT);
                p.setFakeBoldText(true);
                p.setTextSize(w * 0.078f);
                p.setColor(col);
                c.drawText(ellipsize(items[i], w - textX - padX, p), textX, top + rowH * 0.46f, p);
                p.setFakeBoldText(false);
            }
            return;
        }
        if (listSection == 34) { drawEmpty(c, w, h, "Write flash message"); return; } // sim emptyState
        if (listSection == 35) { drawEmpty(c, w, h, "Record audio"); return; } // sim emptyState
        if (listSection == 38) { // Sim gallery: folder size under each name
            String[] items = LIST_ITEMS[38];
            String[] sizes = {"2.7 MB", "0.0 kB", "0.0 kB", "0.0 kB"};
            drawItemRows(c, w, h, items.length, i -> items[i], i -> sizes[i], i -> listIconFor(i));
            return;
        }
        String[] items = LIST_ITEMS[listSection];
        LabelAt subs = null;
        if (listSection == 1) subs = i -> i == 0 ? (alarm()[0].equals("1") ? "On" : "Off") : null; // sim organiser row 0 sub: alarm On/Off
        else if (listSection == 37) subs = i -> i == 1 ? "Dark.nth" : null; // sim theme sub
        drawItemRows(c, w, h, items.length, i -> items[i], subs, i -> listIconFor(i));
    }

