    private void drawConversation(Canvas c, int w, int h) {
        drawTitle(c, w, h, displayName(convoAddress));
        if (convoMsgs.isEmpty()) {
            drawEmpty(c, w, h, "No messages");
            return;
        }
        // Sim v4.89: title carries a right-aligned "n/N" position count.
        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
        p.setTextSize(w * 0.067f);
        p.setColor(Color.parseColor("#DDDDDD"));
        p.setTextAlign(Paint.Align.RIGHT);
        c.drawText((row + 1) + "/" + convoMsgs.size(), w * 0.98f, statusH(h) + titleH(h) * 0.72f, p);
        p.setTextAlign(Paint.Align.LEFT);
        p.setTypeface(Typeface.DEFAULT);

        float areaTop = statusH(h) + titleH(h);
        float areaBot = softTop(h);
        float areaH = areaBot - areaTop;
        float padX = w * (6f / 240f);           // .thread side padding
        float maxBW = w * 0.88f;                // .bubble max-width 88%
        float bPadH = w * (7f / 240f);          // bubble side padding 7px
        float bPadTop = areaH * (14f / 233f);   // bubble top padding 14px
        float bPadBot = areaH * (5f / 233f);
        float bMargin = areaH * (4f / 233f);
        float textSize = w * (14f / 240f);      // bubble text 14px
        float timeSize = w * (11f / 240f);      // <small> time, ~80%
        float lineH = textSize * 1.15f;         // sim line-height 1.15
        float radius = w * (3f / 240f);
        float sepInset = w * (25f / 240f);
        float sepH = areaH * (16f / 233f);
        float sepText = w * (12f / 240f);

        // Items: separator marker (negative) or message index, oldest first.
        List<Integer> items = new ArrayList<>();
        List<String> sepDays = new ArrayList<>();
        String lastDay = null;
        for (int i = 0; i < convoMsgs.size(); i++) {
            String day = dayLabel(convoMsgs.get(i).date);
            if (!day.equals(lastDay)) {
                items.add(-1 - sepDays.size());
                sepDays.add(day);
                lastDay = day;
            }
            items.add(i);
        }

        // Measure item heights.
        int n = items.size();
        float[] ht = new float[n];
        List<List<String>> linesByItem = new ArrayList<>();
        List<Float> widthByItem = new ArrayList<>();
        for (int it = 0; it < n; it++) {
            int v = items.get(it);
            if (v < 0) {
                ht[it] = sepH;
                linesByItem.add(new ArrayList<String>());
                widthByItem.add(0f);
            } else {
                PhoneStore.Sms m = convoMsgs.get(v);
                String body = m.body == null ? "" : m.body;
                List<String> lines = new ArrayList<>();
                float avail = maxBW - 2 * bPadH;
                p.setTextSize(textSize);
                String[] words = body.split(" ");
                StringBuilder line = new StringBuilder();
                for (String word : words) {
                    String candidate = line.length() == 0 ? word : line + " " + word;
                    if (p.measureText(candidate) > avail && line.length() > 0) {
                        lines.add(line.toString());
                        line = new StringBuilder(word);
                    } else {
                        line = new StringBuilder(candidate);
                    }
                }
                lines.add(line.toString());
                float widest = 0f;
                for (String ln : lines) widest = Math.max(widest, p.measureText(ln));
                p.setTextSize(timeSize);
                widest = Math.max(widest, p.measureText(timeLabel(m.date) + " "));
                linesByItem.add(lines);
                widthByItem.add(Math.min(maxBW, widest + 2 * bPadH));
                ht[it] = bPadTop + lines.size() * lineH + bPadBot;
            }
        }

        // Window: as many items as fit, anchored at the newest (bottom).
        int selItem = 0;
        for (int it = 0; it < n; it++) if (items.get(it) == row) { selItem = it; break; }
        int start = n - 1;
        float used = 0f;
        while (start >= 0 && used + ht[start] <= areaH) { used += ht[start]; start--; }
        start++;
        int lastIdx = n - 1;
        if (selItem < start) { // selection above the window: re-anchor at the selection
            start = selItem;
            used = 0f;
            lastIdx = start - 1;
            while (lastIdx + 1 < n && used + ht[lastIdx + 1] <= areaH) { lastIdx++; used += ht[lastIdx]; }
        }

        float y = areaBot - used;
        for (int it = start; it <= lastIdx; it++) {
            int v = items.get(it);
            if (v < 0) {
                // Sim dateSep: centred #555 bar, white 12px text.
                p.setStyle(Paint.Style.FILL);
                p.setColor(Color.parseColor("#555555"));
                c.drawRect(sepInset, y, w - sepInset, y + ht[it], p);
                p.setColor(Color.WHITE);
                p.setTextSize(sepText);
                p.setTextAlign(Paint.Align.CENTER);
                c.drawText(sepDays.get(-1 - v), w / 2f, y + ht[it] * 0.72f, p);
                p.setTextAlign(Paint.Align.LEFT);
            } else {
                PhoneStore.Sms m = convoMsgs.get(v);
                boolean mine = m.type == 2;
                List<String> lines = linesByItem.get(it);
                float bw = widthByItem.get(it);
                float bx = mine ? (w - padX - bw) : padX;
                p.setStyle(Paint.Style.FILL);
                // Sim cascade: theirs #e7e7e7/#222; mine #c9dcf3 with white text.
                p.setColor(Color.parseColor(mine ? "#C9DCF3" : "#E7E7E7"));
                c.drawRoundRect(new android.graphics.RectF(bx, y, bx + bw, y + ht[it]), radius, radius, p);
                int fg = mine ? Color.WHITE : Color.parseColor("#222222");
                float textX = bx + bPadH;
                float baseline = y + bPadTop + lineH * 0.8f;
                for (int li = 0; li < lines.size(); li++) {
                    if (li == 0) {
                        // Inline <small> time prefix on the first line, as in the sim.
                        p.setTextSize(timeSize);
                        p.setColor(fg);
                        String t = timeLabel(m.date) + " ";
                        c.drawText(t, textX, baseline, p);
                        float tw = p.measureText(t);
                        p.setTextSize(textSize);
                        c.drawText(lines.get(0), textX + tw, baseline, p);
                    } else {
                        p.setTextSize(textSize);
                        p.setColor(fg);
                        c.drawText(lines.get(li), textX, baseline, p);
                    }
                    baseline += lineH;
                }
            }
            y += ht[it] + bMargin;
        }
    }

    private void drawRead(Canvas c, int w, int h) {
        if (threads.isEmpty()) return;
        PhoneStore.Sms m = threads.get(readIndex);
        drawTitle(c, w, h, displayName(m.address));
        float top = statusH(h) + titleH(h);
        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
        // v4.89 read box: light panel with dark text, straight under the title.
        float boxTop = top + screenH(h) * 0.02f;
        float boxBot = softTop(h) - screenH(h) * 0.04f;
        p.setStyle(Paint.Style.FILL);
        p.setColor(COL_READ_BG);
        c.drawRect(w * 0.033f, boxTop, w * 0.967f, boxBot, p);
        p.setColor(COL_READ_FG);
        p.setTextSize(w * 0.079f);
        android.graphics.Rect clip = new android.graphics.Rect(
                (int) (w * 0.033f), (int) boxTop, (int) (w * 0.967f), (int) boxBot);
        c.save();
        c.clipRect(clip);
        drawWrapped(c, m.body == null ? "" : m.body, w * 0.075f, w * 0.85f, boxTop + w * 0.075f, w * 0.083f);
        c.restore();
        p.setTypeface(Typeface.DEFAULT);
    }

    // Focus resolves to the To: field until it holds a recipient.
    private int resolvedFocus() {
        return composeNumber.length() == 0 ? 0 : composeFocus;
    }

    private void sendCompose() {
        if (composeNumber.length() == 0) return;
        handler.removeCallbacks(commitTick);
        composeTap.commit();
        if (composeTap.text().length() == 0) return;
        if (actions.sendSms(composeNumber.toString(), composeTap.text())) {
            composeSent = true;
            threads = actions.sms();
            rebuildConvos();
            screen = Screen.THREADS;
            row = 0;
            handler.postDelayed(() -> { composeSent = false; invalidate(); }, 1500);
        }
    }

    private void clearComposeField() {
        if (resolvedFocus() == 0) composeNumber.setLength(0);
        else { handler.removeCallbacks(commitTick); composeTap.clear(); }
    }

    private void drawCompose(Canvas c, int w, int h) {
        // Sim v4.89 unified composer: "New text message" title with the live
        // (1000-len)/01 count, To:/Text: fields with the focus invert
        // (#050505/#fff focused vs #eee/#111), and the attach strip.
        drawTitle(c, w, h, "New text message");
        float top = statusH(h) + titleH(h);
        // Right-aligned character count inside the title row.
        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
        p.setTextSize(w * 0.067f);
        p.setColor(Color.parseColor("#DDDDDD"));
        p.setTextAlign(Paint.Align.RIGHT);
        c.drawText((1000 - composeTap.preview().length()) + "/01", w * 0.97f, statusH(h) + titleH(h) * 0.72f, p);
        p.setTextAlign(Paint.Align.LEFT);

        float pad = w * (7f / 240f); // .smsEditor padding
        float x = pad;
        float fw = w - pad * 2;
        float y = top + pad;
        float labelSize = w * 0.062f;
        float fieldH = w * (34f / 240f) + w * (12f / 240f); // min-height 34 + padding
        int focus = resolvedFocus();
        // To:
        p.setTextSize(labelSize);
        p.setColor(Color.WHITE);
        c.drawText("To:", x, y + labelSize, p);
        y += labelSize + w * (4f / 240f); // label margin-top
        drawComposeField(c, w, x, y, fw, fieldH, composeNumber.toString(), focus == 0);
        y += fieldH + w * (4f / 240f);
        // Text:
        p.setTextSize(labelSize);
        p.setColor(Color.WHITE);
        c.drawText("Text:", x, y + labelSize, p);
        y += labelSize + w * (4f / 240f);
        float stripH = w * (30f / 240f); // sim .attachStrip height
        // Tall screens: keep the strip visible above the softkey bar (sim
        // always shows it) by clamping the Text field to the space left.
        float textH = Math.min(w * (92f / 240f), softTop(h) - y - stripH); // .smsEditor .textField height
        drawComposeField(c, w, x, y, fw, textH, composeTap.preview(), focus == 1);
        y += textH;
        // Attach strip: 30px, centred glyphs.
        p.setTextSize(w * (20f / 240f));
        p.setColor(Color.parseColor("#DDDDDD"));
        p.setTextAlign(Paint.Align.CENTER);
        c.drawText("\u2039 \uD83C\uDF9E \uD83D\uDCF7 \uD83D\uDDBC \u266A \u25A3 \u203A", w * 0.5f, y + stripH * 0.72f, p);
        p.setTextAlign(Paint.Align.LEFT);
        p.setTypeface(Typeface.DEFAULT);
    }

    // Sim v4.89 editor field: 1px #aaa border, #eee/#111, focused inverts to
    // #050505/#fff; text followed by a 2px cursor bar.
    private void drawComposeField(Canvas c, int w, float x, float y, float fw, float fh, String text, boolean focused) {
        p.setStyle(Paint.Style.FILL);
        p.setColor(focused ? Color.parseColor("#050505") : Color.parseColor("#EEEEEE"));
        c.drawRect(x, y, x + fw, y + fh, p);
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(w * (1f / 240f));
        p.setColor(Color.parseColor("#AAAAAA"));
        c.drawRect(x, y, x + fw, y + fh, p);
        p.setStyle(Paint.Style.FILL);
        float fPad = w * (6f / 240f);
        p.setTextSize(w * (15f / 240f) * 1.35f);
        p.setColor(focused ? Color.WHITE : Color.parseColor("#111111"));
        c.save();
        c.clipRect((int) x, (int) y, (int) (x + fw), (int) (y + fh));
        drawWrapped(c, text, x + fPad, fw - fPad * 2, y + fPad + p.getTextSize(), p.getTextSize() * 1.15f);
        c.restore();
    }

    private void drawField(Canvas c, int w, float top, String text, float height) {
        p.setStyle(Paint.Style.FILL);
        p.setColor(COL_READ_BG);
        c.drawRect(w * 0.042f, top, w * 0.958f, top + height, p);
        p.setColor(COL_READ_FG);
        p.setTextSize(w * 0.083f);
        c.drawText(text, w * 0.075f, top + height * 0.68f, p);
    }

    // Sim v4.89 dial page: no title - "NOKIA" label, icon strip (store+gallery),
    // #555 search bar, then the gradient dial-number box (sim .screen = 258px).
    private void drawDialer(Canvas c, int w, int h) {
        if (dialStoreIcon == null) dialStoreIcon = decodeIcon(DIAL_STORE_ICON_B64);
        if (dialGalleryIcon == null) dialGalleryIcon = decodeIcon(DIAL_GALLERY_ICON_B64);
        float areaTop = statusH(h);
        float areaH = softTop(h) - areaTop;
        float u = areaH / 258f;
        float ux = w / 240f;

        p.setTypeface(Typeface.create("sans-serif", Typeface.NORMAL));
        p.setTextAlign(Paint.Align.LEFT);
        p.setColor(Color.parseColor("#888888"));
        p.setTextSize(16 * ux);
        c.drawText("NOKIA", 8 * ux, areaTop + 24 * u, p);

        float stripTop = areaTop + 35 * u;
        float stripH = 55 * u;
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(Math.max(1f, ux));
        p.setColor(Color.parseColor("#222222"));
        c.drawLine(0, stripTop, w, stripTop, p);
        c.drawLine(0, stripTop + stripH, w, stripTop + stripH, p);
        p.setStyle(Paint.Style.FILL);
        float iconS = 38 * ux;
        float iconY = stripTop + (stripH - iconS) / 2f;
        float gap = 6 * ux;
        float x0 = (w - 2 * iconS - gap) / 2f;
        if (dialStoreIcon != null)
            c.drawBitmap(dialStoreIcon, null, new android.graphics.Rect((int) x0, (int) iconY, (int) (x0 + iconS), (int) (iconY + iconS)), p);
        if (dialGalleryIcon != null)
            c.drawBitmap(dialGalleryIcon, null, new android.graphics.Rect((int) (x0 + iconS + gap), (int) iconY, (int) (x0 + 2 * iconS + gap), (int) (iconY + iconS)), p);

        float barTop = stripTop + stripH;
        float barH = 24 * u;
        p.setColor(Color.parseColor("#555555"));
        c.drawRect(0, barTop, w, barTop + barH, p);
        p.setColor(Color.parseColor("#DDDDDD"));
        p.setTextSize(12 * ux);
        c.drawText("⌕ 123", 5 * ux, barTop + barH * 0.72f, p);

        float boxTop = barTop + barH;
        float boxH = 140 * u;
        android.graphics.RectF box = new android.graphics.RectF(0, boxTop, w, boxTop + boxH);
        p.setShader(new android.graphics.LinearGradient(0, boxTop, 0, boxTop + boxH,
                Color.parseColor("#DDDDDD"), Color.parseColor("#AAAAAA"), android.graphics.Shader.TileMode.CLAMP));
        c.drawRoundRect(box, 5 * ux, 5 * ux, p);
        p.setShader(null);
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(Math.max(1f, ux));
        p.setColor(Color.parseColor("#777777"));
        c.drawRoundRect(box, 5 * ux, 5 * ux, p);
        p.setStyle(Paint.Style.FILL);
        p.setColor(Color.parseColor("#111111"));
        p.setTextSize(42 * ux);
        p.setTextAlign(Paint.Align.RIGHT);
        c.drawText(dialNumber.toString(), w - 10 * ux, boxTop + 106 * u, p);
        p.setTextAlign(Paint.Align.LEFT);
        p.setTypeface(Typeface.DEFAULT);
    }

    private void drawAddContact(Canvas c, int w, int h) {
        // Sim v4.89 addcontact: title + two .field boxes (Name / Mobile), active
        // field outlined #2384ad with a cursor bar.
        drawTitle(c, w, h, editingContact ? "Edit contact" : "Add new contact");
        float top = statusH(h) + titleH(h);
        float pad = w * (12f / 240f);          // .contactForm padding
        float x = pad;
        float fw = w - pad * 2;
        float fPad = w * (7f / 240f);          // .field padding
        float labelSize = w * 0.045f;
        float valueSize = w * 0.078f;
        float valueH = w * (20f / 240f);       // .field b min-height
        float fieldH = fPad * 2 + labelSize * 1.2f + valueH;
        float y = top + w * (8f / 240f);       // .field margin
        String[] labels = {"Name", "Mobile"};
        String[] values = {nameTap.preview(), contactNumber.toString()};
        p.setTypeface(Typeface.create("sans-serif-condensed", Typeface.NORMAL));
        for (int fi = 0; fi < 2; fi++) {
            boolean active = contactField == fi;
            p.setStyle(Paint.Style.FILL);
            p.setColor(Color.parseColor("#EDF3F4"));
            c.drawRect(x, y, x + fw, y + fieldH, p);
            p.setStyle(Paint.Style.STROKE);
            p.setStrokeWidth(w * (1f / 240f));
            p.setColor(Color.parseColor("#78909B"));
            c.drawRect(x, y, x + fw, y + fieldH, p);
            if (active) {
                p.setStrokeWidth(w * (2f / 240f));
                p.setColor(Color.parseColor("#2384AD"));
                c.drawRect(x, y, x + fw, y + fieldH, p);
            }
            p.setStyle(Paint.Style.FILL);
            p.setTextAlign(Paint.Align.LEFT);
            p.setTextSize(labelSize);
            p.setColor(Color.parseColor("#35637A"));
            c.drawText(labels[fi], x + fPad, y + fPad + labelSize, p);
            p.setTextSize(valueSize);
            p.setColor(Color.parseColor("#222222"));
            p.setFakeBoldText(true);
            float vy = y + fPad + labelSize * 1.2f + valueH * 0.78f;
            String v = ellipsize(values[fi], fw - fPad * 2 - w * 0.02f, p);
            c.drawText(v, x + fPad, vy, p);
            if (active) { // cursor bar after the text
                float cxPos = x + fPad + p.measureText(v) + w * (2f / 240f);
                p.setColor(Color.parseColor("#222222"));
                c.drawRect(cxPos, vy - valueSize * 0.85f, cxPos + w * (2f / 240f), vy + valueSize * 0.15f, p);
            }
            p.setFakeBoldText(false);
            y += fieldH + w * (8f / 240f);
        }
        p.setTypeface(Typeface.DEFAULT);
    }

